H('394.d.10.F',4,"A synchronous counter avoids ripple delay because all stages:","change state at the same clock edge",["change one after another","skip clock edges","ignore the clock"],"No cascaded delays.")
H('394.d.10.G',3,"A mod-10 counter counts from 0 up to:","9",["10","8","15"],"Ten states, 0-9.")
H('394.d.10.G',4,"To make a 4-bit counter restart after 9, detect the count 1010 and use it to drive the:","reset or clear input",["clock input","power input","output enable only"],"Decoding the invalid count clears the counter.")
H('394.d.10.H',3,"A state machine is a circuit that moves between a limited number of:","defined states",["colors","voltages only","chips"],"Finite states.")
H('394.d.10.H',4,"In a state diagram, the arrows between circles show:","transitions between states",["wire lengths","power ratings","component costs"],"Arrows are transitions.")
H('394.d.10.I',3,"A traffic light controller is an example of a device controlled by a:","state machine",["capacitor","fuse","crystal"],"Lights cycle through states.")
H('394.d.10.I',4,"A vending machine uses a state machine to track the amount of money:","inserted so far",["in the bank","earned last year","spent by others"],"State remembers credit.")
H('394.d.10.J',3,"A state machine can be implemented with flip-flops and:","combinational logic",["only resistors","only wires","only batteries"],"Flip-flops hold state; logic computes next state.")
H('394.d.10.J',4,"Besides discrete logic, a state machine can also be implemented in:","a microcontroller or PLD",["a paper form","a ruler","a fuse box"],"Programmable devices can model states.")

H('394.d.11.A',3,"In a flowchart, a diamond shape represents a:","decision",["start","process","print"],"Diamonds branch on yes/no.")
H('394.d.11.A',4,"Flowcharts help programmers because they show the program's:","logic flow before coding",["price","voltage","color"],"Planning before coding.")
H('394.d.11.B',3,"A variable in a program is used to:","store a value that can change",["draw wires","produce power","measure heat"],"Variables hold data.")
H('394.d.11.B',4,"A loop in a microcontroller program is used to:","repeat instructions",["end power","erase memory","reduce voltage"],"Loops repeat code.")
H('394.d.11.C',3,"Which everyday product contains a microcontroller?","A microwave oven",["A wooden spoon","A paper cup","A brick"],"Appliances use microcontrollers.")
H('394.d.11.C',4,"A robot vacuum uses a microcontroller to:","read sensors and control motors",["cook food","grow plants","print pages"],"Sense and act.")
H('394.d.11.D',3,"A servo motor is designed to move to:","a commanded position",["a random place","one speed forever","no position"],"Servos position on command.")
H('394.d.11.D',4,"Servo position is usually controlled by the width of a:","pulse signal",["water flow","light color","magnet size"],"Pulse width sets the angle.")
H('394.d.11.E',3,"A microcontroller can sense light using a:","photoresistor or light sensor",["spoon","bolt","magnet only"],"Light sensors give input.")
H('394.d.11.E',4,"In a sense-decide-act cycle, the act step is performed by:","outputs such as motors or LEDs",["inputs","batteries","datasheets"],"Outputs act on the world.")
H('394.d.11.F',3,"To read an analog sensor, a microcontroller uses an:","analog-to-digital converter",["digital-to-analog converter","voltage regulator","clock crystal"],"ADCs convert analog to digital.")
H('394.d.11.F',4,"A digital device that cannot interact with the physical world is of limited use because it cannot:","sense inputs or control outputs",["store numbers","use binary","have a program"],"Interaction makes devices useful.")
H('394.d.11.G',3,"Digital control devices such as microcontrollers are valuable because they are:","programmable and flexible",["unchangeable","unable to adapt","always analog"],"Software defines behavior.")
H('394.d.11.G',4,"Compared with hard-wired logic, changing a microcontroller's behavior usually requires only:","changing the program",["rewiring the board","new batteries","a bigger case"],"Reprogramming is easy.")
H('394.d.11.H',3,"Solving a real problem with a microcontroller involves both hardware and:","software",["furniture","paperwork","plumbing"],"Both are needed.")
H('394.d.11.H',4,"When a microcontroller project does not work, a good debugging step is to:","test the hardware and code separately",["change everything at once","ignore the code","hide the board"],"Isolate the fault.")

# ---------------- 395: Robotics I ----------------
H('395.d.1.A',3,"A robotics engineer is most likely to:","design a new robotic system",["answer phones","drive a delivery truck","stock shelves"],"Engineers design systems.")
H('395.d.1.A',4,"A robotics technician most often:","installs, tests, and repairs robots",["files taxes","writes laws","manages a restaurant"],"Technicians support working systems.")
H('395.d.1.B',3,"Which industry uses robots to weld and assemble vehicles?","Automotive manufacturing",["Dairy farming","Barbering","Bookkeeping"],"Car plants rely on robots.")
H('395.d.1.B',4,"A professional who combines robots, sensors, and controllers into a working production cell is a:","robot systems integrator",["court reporter","lifeguard","travel agent"],"Integrators build complete cells.")
H('395.d.1.C',3,"Certifications in robotics show that a worker:","has proven skills in robot programming or safety",["avoided training","owns a robot","wrote a manual"],"Certifications verify skills.")
H('395.d.1.C',4,"A manufacturer such as FANUC offers training certificates for workers who:","program and maintain its robots",["sell groceries","grow crops","paint houses"],"Vendor training is job-specific.")
H('395.d.1.D',3,"Robot designers have an ethical duty to ensure that robots do not:","endanger people nearby",["look modern","use batteries","cost money"],"Safety comes first.")
H('395.d.1.D',4,"Ethics questions about automation include its effect on:","workers' jobs",["paint colors","ocean tides","moon phases"],"Automation changes employment.")
H('395.d.1.E',3,"In a robotics club, welcoming students of all skill levels and backgrounds helps the team:","solve problems with more perspectives",["avoid learning","ignore ideas","lose members"],"Diverse views improve designs.")
H('395.d.1.E',4,"Respecting teammates' cultural differences on a robotics project means:","valuing each member's contributions",["ignoring their input","assigning work by stereotype","excluding quiet members"],"Respect is inclusive.")
H('395.d.1.F',3,"Treating a teammate unfairly because of gender or disability is:","discrimination",["leadership","teamwork","quality control"],"It is unfair and often illegal.")
H('395.d.1.F',4,"An organization that tolerates discrimination can face:","legal penalties and lost trust",["tax credits","faster hiring","public awards"],"Consequences are legal and reputational.")
H('395.d.1.G',3,"Which college degree commonly leads to a career designing robots?","Mechatronics or robotics engineering",["Culinary arts","Music history","Cosmetology"],"Mechatronics combines mechanics and electronics.")
H('395.d.1.G',4,"A community college certificate in automation prepares students for jobs as:","technicians",["judges","pilots","surgeons"],"Certificates prepare technicians.")
H('395.d.1.H',3,"Competing in a robotics competition such as FIRST or VEX helps students build:","teamwork and technical skills",["only trophies","no skills","only free time"],"Competitions teach real skills.")
H('395.d.1.H',4,"A job shadow at a plant with robotic cells lets a student:","see how robots are used on the job",["operate robots unsupervised","take home equipment","skip safety training"],"Shadowing is observation.")
H('395.d.1.I',3,"ABET accredits college programs in applied science, computing, engineering, and engineering:","technology",["tourism","trade","tutoring"],"The T in ABET.")
H('395.d.1.I',4,"Choosing an ABET-accredited robotics program gives students confidence that the program:","meets professional standards",["is free","has no exams","is easy"],"Accreditation reviews quality.")

H('395.d.2.A',3,"On a robot build, the mechanical, electrical, and programming subteams must:","coordinate their designs",["avoid each other","work in secret","compete"],"Subsystems must fit together.")
H('395.d.2.A',4,"A robotics team that shares a common goal is more likely to:","finish the robot on time",["lose parts","miss competitions","avoid testing"],"Shared goals align effort.")
H('395.d.2.B',3,"When a robot arm fails to reach a target, the team should first:","observe and describe the failure",["blame the coder","replace the motor","give up"],"Understand before fixing.")
H('395.d.2.B',4,"A team chooses among three arm designs by comparing each against agreed:","criteria",["colors","nicknames","logos"],"Criteria make comparison fair.")
H('395.d.2.C',3,"A robotics team member shows good attitude by:","helping others learn",["hoarding tools","withholding code","mocking mistakes"],"Sharing builds the team.")
H('395.d.2.C',4,"A team leader running a robot build meeting should:","keep an agenda and invite input",["talk the whole time","skip planning","ignore deadlines"],"Good meetings are organized and inclusive.")

H('395.d.3.A',3,"Planning a robot project includes defining the scope and listing the:","tasks and resources",["colors only","weather","holidays"],"Plans list work and needs.")
H('395.d.3.A',4,"Closing a robot project includes documenting the:","lessons learned",["next lunch","stock price","team's pets"],"Closure records what was learned.")
H('395.d.3.B',3,"To finish a robot before a competition, the team works backward from the:","deadline",["lunch","paint","mascot"],"Backward planning meets deadlines.")
H('395.d.3.B',4,"A task that must finish on time or the whole schedule slips is on the:","critical path",["side street","spare list","wish list"],"Critical tasks have no slack.")
H('395.d.3.C',3,"In a simulated robotics company, a design engineer is responsible for:","creating the robot design",["selling tickets","cooking lunch","cleaning windows"],"Engineers design.")
H('395.d.3.C',4,"A team creating a robot kit to sell might survey potential customers to learn their:","needs",["pets","birthdays","hobbies"],"Market research finds needs.")
H('395.d.3.D',3,"A production plan for a single robot should list the parts, tools, and:","assembly steps",["lunch breaks","parking spots","birthdays"],"Plans cover how to build.")
H('395.d.3.D',4,"Estimating build time for each subassembly helps the team to:","schedule work realistically",["skip testing","order fewer parts","hide delays"],"Estimates drive schedules.")

H('395.d.4.A',3,"A robotics student should pass a safety test before working around:","moving robot arms and power tools",["the cafeteria","the library","the bus"],"Training precedes hazards.")
H('395.d.4.A',4,"Safety training for robot cells emphasizes staying out of the robot's:","work envelope",["paint booth","lunch room","parking lot"],"The envelope is the reach area.")
H('395.d.4.B',3,"Before programming a robot, you should review the manufacturer's:","safety instructions",["sales brochure","coupon","warranty price"],"Manuals contain safety rules.")
H('395.d.4.B',4,"A manual states that a robot's teach pendant should have a working:","emergency stop",["screen saver","sticker","speaker"],"E-stop is essential.")
H('395.d.4.C',3,"ANSI/RIA R15.06 is a U.S. standard for:","industrial robot safety",["school lunches","road signs","garden tools"],"It covers robot safety.")
H('395.d.4.C',4,"OSHA expects employers to protect workers from hazards created by:","robots and automated machinery",["winter weather only","paper cuts only","office plants"],"Machinery hazards are covered.")
H('395.d.4.D',3,"Lithium polymer battery packs used in robots can be hazardous because they may:","overheat or catch fire if damaged",["emit cold","taste sweet","turn to water"],"Damaged LiPo cells can ignite.")
H('395.d.4.D',4,"Hydraulic fluid used in some robots is a hazard because leaks can cause:","slips and skin irritation",["rainbows","sunburn","freezing"],"Fluid is slippery and irritating.")
H('395.d.4.E',3,"Damaged lithium batteries should be taken to:","a battery recycling or hazardous waste site",["the regular trash","a drain","a storage drawer"],"They need special disposal.")
H('395.d.4.E',4,"Used hydraulic oil should be placed in:","a labeled waste container for recycling",["a storm drain","a sink","a flower bed"],"Oil is regulated waste.")
H('395.d.4.F',3,"Regular robot maintenance includes checking cables, fasteners, and:","lubrication points",["wall paint","desk labels","lunch menus"],"Lubrication prevents wear.")
H('395.d.4.F',4,"Loose bolts on a robot arm should be tightened to the specified:","torque",["color","name","price"],"Torque specs prevent damage.")
H('395.d.4.G',3,"Robot batteries should be stored:","in a cool, dry, fire-safe place",["in a hot car","in water","near open flame"],"Proper storage prevents fires.")
H('395.d.4.G',4,"Small robot parts such as screws and servos are best stored in:","labeled bins",["pockets","open floor","the trash"],"Organized storage.")
H('395.d.4.H',3,"Failing to lubricate robot joints can lead to:","wear and mechanical failure",["longer life","higher accuracy","quieter gears forever"],"Friction wears parts.")
H('395.d.4.H',4,"A robot with a damaged cable that was never replaced could:","short-circuit or move unpredictably",["run perfectly","become safer","save power"],"Bad cables cause faults.")

H('395.d.5.A',3,"A computer program controls a robot arm by sending commands to its:","controller",["paint","shell","box"],"Controllers drive actuators.")
H('395.d.5.A',4,"Software that lets you write and download programs to a robot is a:","programming environment",["calendar","map","ledger"],"IDEs support robot code.")
H('395.d.5.B',3,"Calibrating a robot ensures its movements stay:","precise and repeatable",["random","slow","loud"],"Calibration maintains accuracy.")
H('395.d.5.B',4,"Keeping a maintenance log helps a robotics technician to:","track repairs and schedule service",["hide faults","save paper","avoid training"],"Logs support maintenance.")
H('395.d.5.C',3,"In a robot with feedback, a sensor reports the arm's position back to the:","controller",["wheels","paint","floor"],"Feedback closes the loop.")
H('395.d.5.C',4,"Feedback control lets a robot correct its:","errors while moving",["color","name","weight"],"Corrections use measured error.")
H('395.d.5.D',3,"A sensor that measures distance to an object using sound is an:","ultrasonic sensor",["thermocouple","microphone","strain gauge"],"Ultrasonic sensors time echoes.")
H('395.d.5.D',4,"Which sensor helps a line-following robot tell a dark line from a bright floor?","Light or color sensor",["Gyroscope","Thermistor","Encoder"],"Reflectance differs.")

H('395.d.6.A',3,"Newton's second law states that force equals mass times:","acceleration",["velocity","distance","time"],"F = ma.")
H('395.d.6.A',4,"A heavier robot needs more force to speed up. This illustrates Newton's:","second law",["first law","third law","zeroth law"],"Force relates to mass and acceleration.")
H('395.d.6.B',3,"When a small gear drives a larger gear, the output speed is:","lower but torque is higher",["higher and torque is higher","higher but torque is lower","unchanged"],"Speed trades for torque.")
H('395.d.6.B',4,"A 20-tooth driver gear meshed with a 60-tooth driven gear has a gear ratio of:","3:1",["1:3","20:1","6:1"],"60 / 20 = 3.")
H('395.d.6.C',3,"Which of these is one of the six simple machines?","Lever",["Transistor","Battery","Sensor"],"Lever, wheel and axle, pulley, inclined plane, wedge, screw.")
H('395.d.6.C',4,"A wheel and axle in a robot drivetrain is used to:","transmit rotation to move the robot",["store charge","detect light","cool the motors"],"It converts motor rotation into motion.")
H('395.d.6.D',3,"Reversing the polarity of the voltage across a DC motor makes it:","spin in the opposite direction",["stop forever","spin faster","overheat"],"Polarity sets direction.")
H('395.d.6.D',4,"Pulse width modulation controls the speed of a DC motor by changing the:","average voltage delivered",["motor color","wire gauge","shaft length"],"Duty cycle sets average power.")
H('395.d.6.E',3,"A hobby servo typically rotates its output shaft through about:","180 degrees",["10 degrees","3,600 degrees","0 degrees"],"Standard servos span about 180 degrees.")
H('395.d.6.E',4,"In a standard hobby servo, a 1.5 millisecond pulse usually commands the:","center position",["maximum speed","power-off state","full rotation loop"],"1.5 ms is neutral.")

H('395.d.7.A',3,"A longer robot arm that holds a load at its end creates more:","torque at the base joint",["voltage","color","noise"],"Torque = force x distance.")
H('395.d.7.A',4,"Using lightweight, rigid materials for arm links helps reduce the load on the:","motors",["wall","desk","paint"],"Less mass means less torque needed.")
H('395.d.7.B',3,"To lift a heavier payload with the same motor, increase the gear reduction, which raises:","output torque",["input voltage","motor color","payload price"],"Reduction multiplies torque.")
H('395.d.7.B',4,"A motor produces 2 newton-meters of torque and drives through a 5:1 reduction gearbox. The ideal output torque is:","10 newton-meters",["0.4 newton-meters","7 newton-meters","2 newton-meters"],"2 x 5 = 10.")
H('395.d.7.C',3,"The part at the end of a robot arm that grips or manipulates objects is the:","end effector",["base","controller","battery"],"Grippers are end effectors.")
H('395.d.7.C',4,"A gripper that uses a gear and rack to open and close converts rotary motion to:","linear motion",["light","sound","heat"],"Rack and pinion.")

H('395.d.8.A',3,"The design process begins by:","identifying the problem or need",["building the final robot","selling the design","recycling parts"],"Define the problem first.")
H('395.d.8.A',4,"After building a robot prototype, the design process calls for you to:","test it against the requirements",["ship it","ignore results","finish the report only"],"Testing follows building.")
H('395.d.8.B',3,"A competition rule limiting the robot to 18 inches is a:","constraint",["goal","reward","sensor"],"Rules limit designs.")
H('395.d.8.B',4,"Choosing a motor based on measured torque data, not opinion, is a:","fact-based decision",["guess","popularity vote","coin flip"],"Data supports choices.")
H('395.d.8.C',3,"Making changes after testing and then testing again is called:","iteration",["repetition of errors","duplication","deletion"],"Iteration improves designs.")
H('395.d.8.C',4,"A robot misses its target by the same amount every time. The team should:","adjust the design and retest",["ignore it","blame the floor","stop testing"],"Systematic error can be corrected.")
H('395.d.8.D',3,"A decision matrix scores design options against:","weighted criteria",["birthdays","colors only","team names"],"Matrices rank options.")
H('395.d.8.D',4,"Which strategy compares the pros and cons of each option before deciding?","Trade-off analysis",["Coin tossing","Random choice","Skipping the choice"],"Trade-offs weigh benefits and costs.")
H('395.d.8.E',3,"Quality control in robot production checks that each part meets:","specifications",["nicknames","fashion trends","team slogans"],"Specs define acceptable parts.")
H('395.d.8.E',4,"Inspecting gears with a gauge to catch out-of-tolerance parts is an example of:","quality control",["marketing","shipping","recycling"],"Inspection catches defects.")
H('395.d.8.F',3,"Customers judge a robot's quality partly by its reliability and:","ease of use",["shipping box color","company slogan","brand font"],"Usability affects perceived quality.")
H('395.d.8.F',4,"A product that fails often will damage how customers perceive its:","quality and the company's reputation",["color","package","price tag"],"Failures hurt trust.")
H('395.d.8.G',3,"In an engineering notebook for a robot project, you record design decisions and the:","reasons for them",["weather","gossip","lunch"],"Rationale is documented.")
H('395.d.8.G',4,"Notebook entries should be written in:","ink with date and signature",["pencil and erased","random order","code only"],"Permanent, dated entries.")
H('395.d.8.H',3,"A system schematic for a robot shows how the controller connects to the:","motors and sensors",["furniture","windows","desks"],"Schematics show connections.")
H('395.d.8.H',4,"Standard symbols on a robot wiring schematic let different engineers:","read the diagram the same way",["avoid wiring","hide connections","change meanings"],"Standards give shared meaning.")

H('395.d.9.A',3,"When using a hand saw on robot frame material, secure the workpiece with a:","clamp or vise",["your hand","a friend's foot","a towel"],"Clamping prevents injury.")
H('395.d.9.A',4,"Safety glasses are required when using:","cutting, drilling, or grinding tools",["only pencils","only tape","only paper"],"Chips and sparks endanger eyes.")
H('395.d.9.B',3,"A digital caliper can measure a robot part's width to:","a hundredth of an inch or finer",["a mile","a foot only","a guess"],"Calipers read fine increments.")
H('395.d.9.B',4,"Measuring a motor driver's output with a multimeter helps verify the:","voltage supplied to the motor",["robot's name","paint thickness","room temperature"],"Meters verify electrical outputs.")
H('395.d.9.C',3,"Robot simulation software lets a team test code:","before running it on the real robot",["after the competition","without a program","only on paper"],"Simulation reduces risk.")
H('395.d.9.C',4,"A simulation can help a team find path-planning errors without risking:","damage to the robot",["a sunny day","a lunch break","a bus ride"],"Errors occur virtually.")

H('395.d.10.A',3,"A prototype of a robot arm is built to:","test the design before final production",["avoid testing","replace the design","sell immediately"],"Prototypes reveal problems.")
H('395.d.10.A',4,"The first step in producing a prototype is usually to:","create drawings or models",["ship it","paint it","retire it"],"Plans precede building.")
H('395.d.10.B',3,"A 3D printer is useful in prototyping robot parts because it can:","quickly make custom shapes",["wire the controller","weld steel","measure voltage"],"Additive manufacturing is fast for custom parts.")
H('395.d.10.B',4,"Aluminum is often chosen for robot frames because it is strong and:","lightweight",["very heavy","a perfect insulator","magnetic"],"Strength-to-weight ratio.")
H('395.d.10.C',3,"When assembling a robot chassis, fasteners should be tightened until:","snug without stripping threads",["they break","they are loose","they crack"],"Over-tightening strips threads.")
H('395.d.10.C',4,"Wiring a robot neatly, with labels and strain relief, helps with:","troubleshooting and reliability",["color","weight gain","noise"],"Clean wiring is easier to maintain.")
H('395.d.10.D',3,"A robot must lift 2 kg. The team tests it with a 2 kg load to see if it meets the:","requirement",["rumor","mood","logo"],"Tests verify requirements.")
H('395.d.10.D',4,"If a robot passes only 7 of 10 test trials but the requirement is 9 of 10, it:","does not yet meet the requirement",["passes","exceeds it","needs no changes"],"7 is below 9.")
H('395.d.10.E',3,"After tests reveal weak welds, refining the design may include:","strengthening the joints",["removing the design","painting only","ignoring data"],"Fix what testing exposed.")
H('395.d.10.E',4,"Refining a design for quality and safety may include adding:","guards and sensors",["more clutter","extra gaps","sharp edges"],"Safety features improve designs.")
H('395.d.10.F',3,"When presenting a final robot, the team should demonstrate that it:","performs the specified operations",["looks old","is hidden","cannot move"],"Show it meeting its spec.")
H('395.d.10.F',4,"A good presentation of a robot project uses photos, data, and a:","live demonstration",["blank slide","long silence","guess"],"Demos prove performance.")

# ---------------- 396: Robotics II ----------------
H('396.d.1.A',3,"A robot wheel has a diameter of 4 inches. Using 3.14 for pi, how far does it travel in one full rotation?","12.56 inches",["25.12 inches","6.28 inches","50.24 inches"],"C = pi x d = 3.14 x 4.")
H('396.d.1.A',4,"A robot drives 10 feet in 4 seconds. Its average speed is:","2.5 feet per second",["40 feet per second","6 feet per second","0.4 feet per second"],"10 / 4 = 2.5.")
H('396.d.1.B',3,"A robot overshoots its target distance. Which step of a problem-solving model asks whether the fix is reasonable?","Evaluating the solution",["Analyzing the given information","Formulating a plan","Collecting parts"],"Evaluation checks reasonableness.")
H('396.d.1.B',4,"A technician first lists the robot's measured speed and the course length. This is which step?","Analyzing given information",["Justifying the answer","Evaluating the process","Presenting results"],"Listing data is analysis.")
H('396.d.1.C',3,"To quickly check that a travel time of 3 seconds for 6 meters at 2 meters per second is reasonable, use:","mental math",["a ruler","a thermometer","a compass"],"6 / 2 = 3.")
H('396.d.1.C',4,"To plot encoder counts versus time and fit a trend line, an appropriate tool is:","a spreadsheet or graphing software",["a stopwatch alone","a tape measure","a level"],"Software handles data fitting.")
H('396.d.1.D',3,"A robot's turning angle can be communicated precisely with a diagram showing the angle and its:","measurement in degrees",["nickname","price","color"],"Units make angles precise.")
H('396.d.1.D',4,"Describing a robot's path using coordinates on a grid is an example of using:","multiple representations",["slang","guessing","no units"],"Coordinates and diagrams are representations.")
H('396.d.1.E',3,"A flowchart of a robot's decisions is a representation that organizes its:","logic",["paint","wiring colors","shipping"],"Flowcharts show decision logic.")
H('396.d.1.E',4,"Recording each sensor reading in a table by trial number helps the team:","record and compare results",["lose data","avoid analysis","skip testing"],"Tables organize trials.")
H('396.d.1.F',3,"Two robots drive for the same time; one has twice the other's speed. The faster robot's distance is:","twice as far",["half as far","the same","four times as far"],"Distance is proportional to speed.")
H('396.d.1.F',4,"Because a motor's output force and speed trade off at constant power, raising speed lowers:","torque",["voltage rating","color","weight"],"P = torque x speed.")
H('396.d.1.G',3,"To justify that a robot reached 90 degrees, a student should present the measurement and the:","calculation or evidence",["opinion","guess","slogan"],"Evidence supports claims.")
H('396.d.1.G',4,"Precise language in a robotics report means using correct units and terms such as:","torque and velocity",["stuff and things","fast and slow","big and small"],"Technical terms are exact.")

H('396.d.2.A',3,"A well-functioning robotics team has clear roles and:","open communication",["secret plans","no deadlines","one member only"],"Teams need clarity and talk.")
H('396.d.2.A',4,"Team members who each know their role on a competition robot reduce:","confusion and duplicated work",["progress","safety","quality"],"Roles prevent overlap.")
H('396.d.2.B',3,"When the robot's code and hardware disagree, the programmers and builders should:","troubleshoot together",["blame each other","work separately","quit"],"Joint troubleshooting finds causes.")
H('396.d.2.B',4,"Sharing test data with all team members helps them to:","make informed decisions together",["avoid the problem","hide failures","duplicate effort"],"Shared data aligns decisions.")
H('396.d.2.C',3,"On a project, following the project lead's decisions even when you disagree is part of:","working as a team",["breaking rules","going alone","skipping tasks"],"Teams need direction.")
H('396.d.2.C',4,"During a robot test, the safety officer tells everyone to stand back. You should:","comply immediately",["finish your task first","argue","ignore it"],"Safety directions are followed at once.")
H('396.d.2.D',3,"Team norms might include how to resolve disagreements and:","how to run meetings",["what to wear","which song to play","who sits where"],"Norms set working rules.")
H('396.d.2.D',4,"Setting team norms at the start of a project helps prevent:","conflicts over expectations",["progress","communication","planning"],"Agreed norms reduce friction.")
H('396.d.2.E',3,"Setting a shared goal like finishing the robot by week 6 helps the team to:","focus and measure progress",["avoid effort","skip testing","lose direction"],"Goals give direction.")
H('396.d.2.E',4,"At a robotics competition, teams that cooperate with alliance partners often:","score more together",["lose points","break rules","avoid matches"],"Alliances combine strengths.")

H('396.d.3.A',3,"A work breakdown structure divides a robot project into smaller:","tasks",["colors","budgets","teams only"],"WBS lists tasks.")
H('396.d.3.A',4,"In project management, risk management involves identifying problems that:","might occur and planning responses",["already ended","never happen","cost nothing"],"Plan for possible issues.")
H('396.d.3.B',3,"A Gantt chart for a robot build shows each task as a bar along a:","timeline",["circuit","motor","gear"],"Gantt charts plot time.")
H('396.d.3.B',4,"If a part shipment is late, the project manager should update the:","schedule",["mascot","logo","slogan"],"Delays change the schedule.")
H('396.d.3.C',3,"In a simulated robotics enterprise, the purchasing role orders:","parts and materials",["lunches","tickets","trophies"],"Purchasing buys supplies.")
H('396.d.3.C',4,"A real or simulated enterprise helps students understand how departments depend on:","one another",["no one","chance","weather"],"Departments are interdependent.")
H('396.d.3.D',3,"A Project Management Plan for a robot lists the scope, schedule, budget, and:","team roles",["pet names","lunch menu","TV schedule"],"Plans assign responsibilities.")
H('396.d.3.D',4,"Employing the plan during production means the team:","follows and updates it as work proceeds",["files it away","ignores it","burns it"],"Plans are living documents.")

H('396.d.4.A',3,"A robotics student should retake safety training when:","new equipment or hazards are introduced",["it is lunchtime","grades are posted","rain starts"],"New hazards need new training.")
H('396.d.4.A',4,"Passing a lab safety assessment before using a CNC mill or laser cutter shows the student can:","operate it without endangering others",["ignore the manual","skip PPE","work unsupervised always"],"Assessment verifies safe use.")
H('396.d.4.B',3,"A robot's lockout/tagout procedure ensures that before maintenance the robot is:","de-energized and cannot restart",["running at full speed","left on standby","painted"],"LOTO prevents unexpected motion.")
H('396.d.4.B',4,"Manual instructions about a robot's restricted space tell workers to:","stay outside its reach when it is powered",["stand inside it","touch moving parts","bypass guards"],"Stay clear of live robots.")
H('396.d.4.C',3,"A robot lab's battery charging area should have a:","fire-safe charging bag or container",["pile of paper","open flame","bucket of water on the charger"],"Containment limits fire risk.")
H('396.d.4.C',4,"Compressed air cylinders used in pneumatic robots are hazards because they are:","under high pressure",["too cold","too sweet","made of paper"],"Stored pressure can injure.")
H('396.d.4.D',3,"Used coolant and lubricants from robot maintenance should be:","collected and disposed of as regulated waste",["poured outside","flushed","dumped in the trash"],"Fluids need proper disposal.")
H('396.d.4.D',4,"Electronic waste from retired robots should go to:","a certified e-waste recycler",["a landfill dumpster","a river","a classmate's locker"],"Certified recyclers handle toxics.")
H('396.d.4.E',3,"In a robotics lab, food and drinks should be kept:","out of the work area",["on the workbench","on the robot","near the batteries"],"Spills damage electronics and cause hazards.")
H('396.d.4.E',4,"Before leaving the lab, a student should:","clean the workspace and return tools",["leave tools out","unplug nothing","hide trash"],"Lab guidelines require cleanup.")
H('396.d.4.F',3,"Hand tools in a robotics lab should be stored on a:","labeled tool board or shadow board",["pile on the floor","windowsill","chair"],"Shadow boards show what is missing.")
H('396.d.4.F',4,"Flammable materials such as solvents should be stored in:","an approved flammable-storage cabinet",["open shelves","a backpack","a warm closet"],"Cabinets limit fire risk.")
H('396.d.4.G',3,"An inventory system for robot parts helps a team to:","know what parts are available",["lose parts","guess counts","overspend"],"Inventory tracks stock.")
H('396.d.4.G',4,"Labeling bins by part number and tracking checkouts is an example of:","inventory control",["packaging","marketing","payroll"],"Controlled tracking.")
H('396.d.4.H',3,"If a team ignores a worn belt on a conveyor robot, the belt may:","snap and cause injury or damage",["last forever","become stronger","quiet the robot"],"Worn parts fail.")
H('396.d.4.H',4,"Documenting maintenance helps protect a team from claims of:","negligence",["success","efficiency","teamwork"],"Records show due care.")

H('396.d.5.A',3,"A program for an autonomous robot is typically written on a computer and then:","downloaded to the robot controller",["printed","painted","mailed"],"Code is uploaded to the controller.")
H('396.d.5.A',4,"An IDE is a tool programmers use to:","write, test, and debug code",["wire robots","paint parts","measure torque"],"Integrated development environment.")
H('396.d.5.B',3,"When a robot's sensor reads incorrectly, a technician should first check:","wiring and sensor mounting",["the paint","the logo","the lunch"],"Check the simple causes first.")
H('396.d.5.B',4,"Isolating a fault to a subsystem, such as the drivetrain or arm, is an example of:","systematic troubleshooting",["random guessing","giving up","replacing everything"],"Narrowing down the fault.")
H('396.d.5.C',3,"A proportional controller adjusts motor power based on the:","error between target and actual",["robot's price","shape of the base","time of day"],"Correction is proportional to error.")
H('396.d.5.C',4,"A line-following robot corrects its path by comparing sensor readings to a:","target value",["random number","logo","motor color"],"The setpoint is the target.")
H('396.d.5.D',3,"A gyroscope sensor on a robot measures its:","rotation or turning rate",["color","price","taste"],"Gyros sense angular rate.")
H('396.d.5.D',4,"An encoder on a motor shaft is used to measure:","rotation distance and speed",["room temperature","light color","sound volume"],"Encoders count shaft rotation.")

H('396.d.6.A',3,"A robot speeds up from 0 to 2 meters per second in 4 seconds. Its average acceleration is:","0.5 meters per second squared",["8 meters per second squared","2 meters per second squared","0.2 meters per second squared"],"2 / 4 = 0.5.")
H('396.d.6.A',4,"Velocity differs from speed because velocity includes:","direction",["color","mass","price"],"Velocity is a vector.")
H('396.d.6.B',3,"A hinge joint that rotates about a single axis provides how many degrees of freedom?","one",["three","six","zero"],"One axis, one degree.")
H('396.d.6.B',4,"A robot arm that can position its gripper anywhere in 3D space and orient it in any direction needs at least how many degrees of freedom?","six",["two","three","four"],"Three for position, three for orientation.")
H('396.d.6.C',3,"Angular momentum of a spinning part depends on its moment of inertia and its:","angular velocity",["color","price","length of wire"],"L = I x omega.")
H('396.d.6.C',4,"If a spinning arm pulls its mass closer to the axis while angular momentum is conserved, its rotation speed:","increases",["decreases","stops","reverses"],"Smaller I means greater omega.")
H('396.d.6.D',3,"Impulse equals force multiplied by:","time",["distance","mass","volume"],"J = F x t.")
H('396.d.6.D',4,"Extending the time over which a robot gripper stops a falling part reduces the:","force on the part",["part's mass","gravity","gripper color"],"Same impulse over longer time means less force.")
H('396.d.6.E',3,"A robot wheel spinning in place shows which kind of motion?","rotational motion",["translational motion","oscillatory motion","no motion"],"Spinning is rotation.")
H('396.d.6.E',4,"A pendulum-like swing of a robot's tail is an example of:","oscillatory motion",["straight-line motion","no motion","random heat"],"Back-and-forth repeating motion.")
H('396.d.6.F',3,"An H-bridge circuit allows a microcontroller to control a DC motor's:","direction and speed",["color","weight","name"],"H-bridges reverse polarity and support PWM.")
H('396.d.6.F',4,"A motor's stall current is the current drawn when the shaft is:","blocked and not turning",["spinning freely","disconnected","removed"],"Stall draws maximum current.")
H('396.d.6.G',3,"A continuous-rotation servo is controlled to set its:","speed and direction",["color","weight","shape"],"The pulse sets speed, not position.")
H('396.d.6.G',4,"A servo holding a heavy load may draw more current and need:","an adequate power supply",["a smaller battery","no wiring","less torque rating"],"Loaded servos draw more current.")
H('396.d.6.H',3,"A light sensor reads 200 on white and 800 on black. A good threshold to separate them is about:","500",["100","900","0"],"The midpoint is (200 + 800) / 2.")
H('396.d.6.H',4,"If a sensor reading is above the threshold, the program's if-statement can trigger an:","action such as turning",["error only","power-off always","color change"],"Thresholds drive decisions.")
H('396.d.6.I',3,"To turn a robot 90 degrees in place, the wheels must travel an arc length determined by the robot's:","track width",["color","name","logo"],"Wheel separation sets the turning arc.")
H('396.d.6.I',4,"A robot must drive along the hypotenuse of a 3-by-4 foot right triangle. The straight-line distance is:","5 feet",["7 feet","12 feet","3.5 feet"],"Pythagorean theorem: 3-4-5.")
H('396.d.6.J',3,"An encoder reports 360 counts per revolution. After 720 counts, the wheel has turned:","two revolutions",["half a revolution","one revolution","four revolutions"],"720 / 360 = 2.")
H('396.d.6.J',4,"To drive exactly 24 inches with a wheel of 8-inch circumference, the robot needs how many wheel rotations?","three",["two","four","eight"],"24 / 8 = 3.")
H('396.d.6.K',3,"Path planning with geometry and several sensors lets a robot find a route around:","obstacles",["colors","batteries","speeds"],"Planning avoids obstacles.")
H('396.d.6.K',4,"A robot uses ultrasonic and infrared sensors together to improve its path planning. This is called:","sensor fusion",["sensor deletion","wheel locking","battery balancing"],"Combining sensors improves reliability.")

H('396.d.7.A',3,"Syntax in programming means the:","rules for writing valid code",["color of the code","speed of the CPU","size of the screen"],"Syntax defines valid form.")
H('396.d.7.A',4,"A missing semicolon or bracket in code will most likely cause a:","syntax error",["faster program","new feature","power surge"],"The compiler cannot parse it.")
H('396.d.7.B',3,"Comments in a program help others to:","understand what the code does",["run it faster","hide it","delete it"],"Comments explain intent.")
H('396.d.7.B',4,"Good documentation for a robot program includes comments and a:","description of the sensors and logic",["list of jokes","sales pitch","team photo"],"Documentation aids maintenance.")
H('396.d.7.C',3,"An if-else structure lets a program:","choose between actions based on a condition",["repeat forever","delete variables","reduce voltage"],"Conditionals select paths.")
H('396.d.7.C',4,"Boolean logic in a program uses values that are either:","true or false",["red or blue","big or small","hot or cold"],"Boolean means two values.")
H('396.d.7.D',3,"Pseudocode is a way to describe an algorithm using:","plain language steps",["machine code","schematic symbols","wire colors"],"It is code-like English.")
H('396.d.7.D',4,"In a flowchart, an oval is used for:","start and end",["decisions","sensors","motors"],"Terminators are ovals.")
H('396.d.7.E',3,"An algorithm that stops the robot if the distance sensor reads under 10 centimeters uses a:","conditional statement",["loop counter only","comment","header"],"It tests a condition.")
H('396.d.7.E',4,"In pseudocode, IF obstacle detected THEN turn right is an example of:","a selection structure",["a variable","a comment","a sensor"],"Selection chooses an action.")
H('396.d.7.F',3,"To repeat an action exactly 5 times, a programmer uses a:","counting loop",["comment","header","constant"],"A for loop counts iterations.")
H('396.d.7.F',4,"An infinite loop in a robot's main program is often used so the robot:","keeps running and checking sensors",["turns off immediately","skips inputs","never starts"],"Main loops run continuously.")
H('396.d.7.G',3,"Storing a sensor reading in a variable lets the program:","use and compare the value later",["erase the sensor","stop the robot","change the battery"],"Variables hold readings.")
H('396.d.7.G',4,"Feedback in code means using sensor values to adjust:","outputs such as motor power",["file names","comments","screen colors"],"Sensor data drives outputs.")
H('396.d.7.H',3,"A command that sets a motor's power to 50 percent is an:","output command",["input command","comment","syntax error"],"It drives an actuator.")
H('396.d.7.H',4,"A variable named speed can store the motor power so it can be:","reused and changed in the program",["only printed","never edited","deleted by hardware"],"Variables are changeable.")
H('396.d.7.I',3,"A switch (case) structure is useful when a program must choose among:","many possible actions",["two colors only","no options","hardware parts"],"Switch handles multiple cases.")
H('396.d.7.I',4,"A goto or jump command changes the program's:","next instruction to execute",["voltage","motor","sensor"],"Jumps redirect flow.")
H('396.d.7.J',3,"A function in a robot program is a reusable block that:","performs a specific task",["stores sensors","draws wires","turns off power"],"Functions encapsulate tasks.")
H('396.d.7.J',4,"Using a function for turning left 90 degrees avoids repeating:","the same code in many places",["the battery","the motor","the sensor"],"Reuse reduces errors.")

H('396.d.8.A',3,"Robotic arm links connected by joints form a:","kinematic chain",["voltage divider","logic gate","power supply"],"Links and joints form a chain.")
H('396.d.8.A',4,"The space a robot arm can reach is called its:","reach envelope",["power curve","battery map","shipping zone"],"Envelope = reachable workspace.")
H('396.d.8.B',3,"A joint motor produces half a newton-meter of torque through an ideal 10:1 gearbox. The output torque is:","5 newton-meters",["0.05 newton-meters","10.5 newton-meters","0.5 newton-meters"],"0.5 x 10 = 5.")
H('396.d.8.B',4,"Increasing a gear reduction usually trades away output:","speed",["torque","strength","force"],"More reduction means slower output.")
H('396.d.8.C',3,"A four-bar linkage in a gripper helps keep the fingers:","parallel as they close",["spinning","upside down","cold"],"Parallel linkage keeps jaws aligned.")
H('396.d.8.C',4,"A worm gear in a gripper actuator is often chosen because it:","resists back-driving and holds its position",["spins freely","has no friction","needs no motor"],"Worm drives self-lock.")

H('396.d.9.A',3,"The step where a team compares possible designs against the requirements is:","evaluating alternatives",["shipping","painting","retiring"],"Alternatives are compared.")
H('396.d.9.A',4,"During the design process, requirements and constraints are written:","before choosing a design",["after delivering the robot","never","after the competition"],"They guide the choice.")
H('396.d.9.B',3,"A battery that can only supply 10 amps limits a design with motors that need 15 amps. This is a:","power constraint",["color constraint","name constraint","size reward"],"Supply limits the design.")
H('396.d.9.B',4,"Making design choices using test data and calculations is:","evidence-based reasoning",["guesswork","luck","imitation"],"Evidence supports decisions.")
H('396.d.9.C',3,"A formal test plan states the procedure, the measurements, and the:","pass or fail criteria",["team jokes","lunch plans","logo ideas"],"Criteria define success.")
H('396.d.9.C',4,"After analyzing test results, the next step in reiteration is to:","revise the design and test again",["stop the project","remove the data","skip testing"],"Iterate to improve.")
H('396.d.9.D',3,"To defend a design decision to judges, a team should present:","data and reasoning",["opinions only","jokes","guesses"],"Evidence persuades.")
H('396.d.9.D',4,"When two designs score equally in a decision matrix, the team might:","add or reweight criteria and compare again",["flip a coin only","pick randomly","ignore the matrix"],"Refine the criteria.")
H('396.d.9.E',3,"A control chart tracks a measurement over time to spot:","variation or drift in quality",["team size","paint color","lunch cost"],"Control charts detect process changes.")
H('396.d.9.E',4,"If 12 of 100 produced arms are out of tolerance, the defect rate is:","12 percent",["88 percent","1.2 percent","100 percent"],"12 / 100.")
H('396.d.9.F',3,"Six Sigma is a method for improving quality by reducing:","defects and variation",["employees","customers","profits"],"The goal is near-zero defects.")
H('396.d.9.F',4,"Six Sigma's DMAIC stands for define, measure, analyze, improve, and:","control",["copy","cancel","create"],"The final phase is control.")
H('396.d.9.G',3,"In a robot engineering notebook, test data should be recorded with the:","date, conditions, and results",["team's gossip","random doodles","menus"],"Context makes data useful.")
H('396.d.9.G',4,"A well-kept notebook can later help a team to:","reproduce and defend design decisions",["hide errors","replace testing","avoid reports"],"Records support defense and repeatability.")
H('396.d.9.H',3,"On a robot wiring schematic, a line between the battery and the motor driver shows a:","electrical connection",["paint line","gear mesh","software comment"],"Lines are wires.")
H('396.d.9.H',4,"Before powering a robot built from a schematic, check polarity to avoid:","damaging components",["extra speed","brighter lights","shorter wires"],"Reverse polarity can destroy parts.")

H('396.d.10.A',3,"A torque screwdriver is used to tighten fasteners to a:","specified torque",["random tightness","maximum force always","guess"],"It limits tightening.")
H('396.d.10.A',4,"Soldering iron tips and drill bits should be kept:","clean and in good condition",["dirty","bent","loose in pockets"],"Maintained tools are safer.")
H('396.d.10.B',3,"An oscilloscope helps analyze a robot's motor-driver signals by showing the signal's:","waveform over time",["price","paint","shape of the case"],"Scopes display waveforms.")
H('396.d.10.B',4,"A dial indicator is used to measure small amounts of:","runout or movement",["voltage","temperature","weight"],"Dial indicators detect small displacement.")
H('396.d.10.C',3,"Assigning a part number to each component of a robot lets a team:","track and order parts accurately",["lose parts","hide parts","repaint parts"],"Part numbers identify items.")
H('396.d.10.C',4,"A bill of materials for a robot lists each part's quantity and:","part number",["owner's age","paint recipe","weather"],"BOMs identify parts.")
H('396.d.10.D',3,"Physics-based robot simulators model a robot's:","motion and sensor behavior",["paint color","price","marketing"],"They simulate dynamics.")
H('396.d.10.D',4,"To validate a simulation, compare its results with:","measurements from the real robot",["guesses","last year's weather","opinions"],"Real data validates models.")

H('396.d.11.A',3,"The first step in designing a robot that sorts objects by color is to define its:","requirements",["paint job","logo","carrying case"],"Requirements drive design.")
H('396.d.11.A',4,"Sketching the layout of sensors, motors, and the controller before building is part of:","system design",["shipping","accounting","marketing"],"Layout planning.")
H('396.d.11.B',3,"Choosing sheet aluminum versus plastic for a chassis involves comparing strength, weight, and:","cost",["color names","team size","season"],"Materials trade-offs.")
H('396.d.11.B',4,"A laser cutter or CNC router is chosen when parts need:","accurate, repeatable cuts",["random shapes","no precision","hand painting"],"CNC gives precision.")
H('396.d.11.C',3,"A bump switch on a robot is used to detect:","physical contact",["sound","color","temperature"],"Touch sensor.")
H('396.d.11.C',4,"Mounting a distance sensor too low on a robot may cause it to:","read the floor or miss obstacles",["fix errors","use less power","gain speed"],"Placement affects readings.")
H('396.d.11.D',3,"While building the robot, a team should verify each subsystem works before:","integrating it with the rest",["testing it","painting it","reading about it"],"Test pieces before combining.")
H('396.d.11.D',4,"Securing wires with zip ties and strain relief prevents:","loose connections during motion",["lower voltage","extra speed","sensor color"],"Strain relief protects connectors.")
H('396.d.11.E',3,"Formal testing of a robot should be done using:","a written procedure",["improvisation","a guess","random trials"],"Procedures make tests repeatable.")
H('396.d.11.E',4,"Repeating a test several times and averaging results reduces the effect of:","random error",["design","gravity","requirements"],"Averaging smooths noise.")
H('396.d.11.F',3,"A robot sorts objects correctly only 80 percent of the time, but the goal is 95 percent. The team should:","refine the design and retest",["declare success","ignore the goal","stop testing"],"80 is below 95.")
H('396.d.11.F',4,"Refining the design for quality and safety could involve adding:","limit switches or emergency stops",["sharp edges","loose wires","unprotected pinch points"],"Safety features.")
H('396.d.11.G',3,"A final presentation of the robot should explain the design process and the:","results of testing",["team's snacks","unrelated stories","other robots' secrets"],"Results show success.")
H('396.d.11.G',4,"Using video of the robot in action during a presentation helps the audience:","see the performance clearly",["miss the details","lose interest","skip questions"],"Video demonstrates behavior.")

B.balance()
B.save(os.path.join(os.path.dirname(os.path.abspath(__file__)), '..', 'batches', 'cte_58.jsonl'))
